mapper.select:
select ASSET_CONFIG_MON_DETAIL.ASSET_CONFIG_CODE assetConfigCode, ASSET_CONFIG_MON_DETAIL.ASSET_TYPE assetType, ASSET_CONFIG_MON_DETAIL.ASSET_MONTH assetMonth, ASSET_CONFIG_MON_DETAIL.CUR_END_AMT curEndAmt,ASSET_CONFIG_MON_DETAIL.CUR_INV_AMT curInvAmt from ASSET_CONFIG_MON_DETAIL where 1=1
and ASSET_CONFIG_MON_DETAIL.ASSET_CONFIG_CODE = #{assetConfigCode,jdbcType=VARCHAR}
and ASSET_CONFIG_MON_DETAIL.ASSET_TYPE = #{assetType,jdbcType=VARCHAR}
